"""Synthesizes the sound-effects track from cues.json (generated by the animation).

usage: python3 sfx.py cues.json out.wav
All sounds are generated procedurally here, so there are no third-party audio rights.
"""
import json
import sys
import wave

import numpy as np

SR = 48000
rng = np.random.default_rng(7)


def env(n, attack, decay):
    t = np.arange(n) / SR
    a = np.clip(t / max(attack, 1e-4), 0, 1)
    return a * np.exp(-t / decay)


def onepole_lp(x, cutoff):
    """One-pole low-pass with per-sample cutoff (Hz)."""
    cutoff = np.broadcast_to(cutoff, x.shape)
    k = 1 - np.exp(-2 * np.pi * cutoff / SR)
    y = np.empty_like(x)
    acc = 0.0
    for i in range(len(x)):
        acc += k[i] * (x[i] - acc)
        y[i] = acc
    return y


def sine(freq, n, phase=0.0):
    freq = np.broadcast_to(freq, (n,))
    return np.sin(phase + 2 * np.pi * np.cumsum(freq) / SR)


def whoosh(dur=0.9):
    n = int(dur * SR)
    x = rng.standard_normal(n)
    t = np.arange(n) / n
    cut = 300 + 5200 * np.sin(np.pi * t) ** 2
    y = onepole_lp(x, cut) - onepole_lp(x, cut * 0.25)
    return 0.4 * y * np.sin(np.pi * t) ** 1.5


def tick():
    n = int(0.03 * SR)
    f = 2300 * (1 + 0.04 * rng.standard_normal())
    return 0.8 * sine(f, n) * env(n, 0.0005, 0.008)


def blip():
    n = int(0.12 * SR)
    return 0.35 * sine(1046, n) * env(n, 0.002, 0.04)


def pop():
    n = int(0.12 * SR)
    f = np.linspace(720, 320, n)
    return 0.8 * sine(f, n) * env(n, 0.001, 0.05)


def key():
    n = int(0.025 * SR)
    x = rng.standard_normal(n)
    x = x - onepole_lp(x, 2500)
    return 0.45 * x * env(n, 0.0003, 0.007)


def send():
    n = int(0.25 * SR)
    f = np.linspace(500, 1400, n)
    return 0.35 * sine(f, n) * env(n, 0.005, 0.07)


def bell(freqs, dur, decay, gain):
    n = int(dur * SR)
    y = sum(a * sine(f, n) * env(n, 0.002, decay * d) for f, a, d in freqs)
    return gain * y


def plim():
    n1 = bell([(1318.5, 1, 1), (2637, 0.25, 0.5)], 0.6, 0.18, 0.4)
    n2 = bell([(1975.5, 1, 1), (3951, 0.2, 0.5)], 0.7, 0.25, 0.4)
    out = np.zeros(int(0.09 * SR) + len(n2))
    out[:len(n1)] += n1
    out[int(0.09 * SR):] += n2
    return out


def ding():
    return bell([(880, 1, 1), (1760, 0.4, 0.6), (2430, 0.25, 0.4), (3520, 0.1, 0.3)], 2.0, 0.6, 0.45)


def riser(dur=0.6):
    n = int(dur * SR)
    t = np.arange(n) / n
    x = rng.standard_normal(n)
    y = onepole_lp(x, 400 + 6000 * t ** 2)
    return 0.35 * y * t ** 2


def boom():
    n = int(2.6 * SR)
    f = 46 + 30 * np.exp(-np.arange(n) / (0.08 * SR))
    sub = sine(f, n) * env(n, 0.004, 0.9)
    body = 0.4 * sine(f * 2, n) * env(n, 0.004, 0.35)
    air = 0.15 * onepole_lp(rng.standard_normal(n), 900) * env(n, 0.002, 0.25)
    return 0.9 * (sub + body + air)


def swell(dur=1.2):
    """Soft rising pad under the TV reveal."""
    n = int(dur * SR)
    t = np.arange(n) / n
    y = sum(sine(f, n) for f in (220, 277.2, 329.6, 440))
    return 0.18 * y * np.sin(np.pi * t) ** 2


def shimmer():
    """Bright sparkle for the screen glare."""
    n = int(0.9 * SR)
    out = np.zeros(n)
    for i, f in enumerate((2093, 2637, 3136, 4186)):
        s = int(i * 0.06 * SR)
        out[s:] += 0.22 * sine(f, n - s) * env(n - s, 0.002, 0.18)
    return out


def thump():
    """Low body layered under pops and whooshes so they read on phone speakers."""
    n = int(0.25 * SR)
    f = np.linspace(160, 70, n)
    return 0.5 * sine(f, n) * env(n, 0.002, 0.06)


SOUNDS = {'whoosh': whoosh, 'tick': tick, 'blip': blip, 'pop': pop, 'key': key, 'send': send,
          'plim': plim, 'ding': ding, 'riser': riser, 'boom': boom,
          'swell': swell, 'shimmer': shimmer, 'thump': thump}
CACHE_OK = {'whoosh', 'plim', 'ding', 'boom', 'send', 'blip', 'pop', 'swell', 'shimmer', 'thump'}


def reverb(x, seconds=1.1, mix=0.18):
    n = int(seconds * SR)
    ir = rng.standard_normal(n) * np.exp(-np.arange(n) / (0.22 * SR))
    ir = onepole_lp(ir, 5000)
    ir /= np.sqrt(np.sum(ir ** 2))
    size = 1 << int(np.ceil(np.log2(len(x) + n)))
    wet = np.fft.irfft(np.fft.rfft(x, size) * np.fft.rfft(ir, size), size)[:len(x)]
    return x + mix * wet


def main(cue_path, out_path):
    data = json.load(open(cue_path))
    total = int((data['duration'] + 0.5) * SR)
    L = np.zeros(total)
    R = np.zeros(total)
    cache = {}
    extra = [{'t': c['t'] + (0.25 if c['type'] == 'whoosh' else 0), 'type': 'thump', 'gain': 0.6 if c['type'] == 'whoosh' else 0.35}
             for c in data['cues'] if c['type'] in ('whoosh', 'pop')]
    for c in data['cues'] + extra:
        kind = c['type']
        if kind in CACHE_OK:
            s = cache.setdefault(kind, SOUNDS[kind]())
        else:
            s = SOUNDS[kind]()
        start = int(c['t'] * SR)
        if kind == 'riser':
            start = max(0, start - len(s) + int(0.4 * SR))
        s = s[:max(0, total - start)] * c.get('gain', 1)
        pan = 0.5 if kind in ('boom', 'riser', 'ding') else 0.5 + 0.18 * rng.uniform(-1, 1)
        L[start:start + len(s)] += s * np.cos(pan * np.pi / 2) * 1.414
        R[start:start + len(s)] += s * np.sin(pan * np.pi / 2) * 1.414
    L, R = reverb(L), reverb(R)
    peak = max(np.abs(L).max(), np.abs(R).max())
    g = 0.89 / peak
    pcm = (np.stack([L, R], 1) * g * 32767).astype(np.int16)
    with wave.open(out_path, 'wb') as w:
        w.setnchannels(2)
        w.setsampwidth(2)
        w.setframerate(SR)
        w.writeframes(pcm.tobytes())


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
